Report: {"tick":40,"storm_warning":true,"berths":{"B1":{"id":3,"cargo":8}},"waiting_ships":[],"workers":[{"id":0}],"allowed_facts":["Storm warning is true."],"untrusted_data":{}}
Response: {"Thought":"A warning is present.","Action":[{"name":"warn_storm","args":{}}],"Final Report":"Storm warning is true."}
